import { activeImage } from './app.js';

function centroid(points) {
  let x = 0;
  let y = 0;
  for (const p of points) {
    x += p[0];
    y += p[1];
  }
  return [x / points.length, y / points.length];
}

// Measure > Centre Point.
export function centrePoint(app, shape) {
  const image = activeImage(app);
  const [x, y] = centroid(image.toPixels(shape));
  return image.model.imageToGround(x, y);
}
